mapper.select:
WITH labs AS ( SELECT Distinct p.stateno, fn_to_date(s.calc_collection_date, 'MM/DD/YYYY') calc_collection_date FROM person_doc_association p, std_hiv_eclrs_doc s WHERE p.document_id = s.document_id --AND p.dissassociation_date IS NULL AND s.interpret_cd in ('QUAN_VL','DET_QUAN_VL','ND_QUAN_VL') ), final_labs AS ( SELECT Distinct a.curr_nyehms_stateno stateno, r.calc_ehars_hiv_dx_dt, r.RIA_FLAGGED_DATE , sysdate - fn_to_date(r.calc_ehars_hiv_dx_dt, 'MM/DD/YYYY') days FROM nyehms_ria_doc a, all_ria_vw r WHERE a.complete_date IS NULL AND Nvl(a.ria_eligible, 'X') != 'N' AND r.curr_nyehms_stateno = a.curr_nyehms_stateno AND r.calc_ehars_hiv_dx_dt IS NOT NULL AND NOT EXISTS (SELECT 1 FROM labs l WHERE r.curr_nyehms_stateno = l.stateno AND l.calc_collection_date > fn_to_date(r.calc_ehars_hiv_dx_dt, 'MM/DD/YYYY')) ) SELECT stateno, calc_ehars_hiv_dx_dt, round(days) days, TO_CHAR(RIA_FLAGGED_DATE, 'MM/DD/YYYY') RIA_FLAGGED_DATE FROM final_labs
where days > #{p_dateRange}
where days BETWEEN #{p_dateRangeFrom} AND #{p_dateRangeTo}
